var n=`1295-vatapa`;var t=`world-1295`;var a=`BR`;var s=`south-america`;var r=4;var o=66;var l={en:`Vatapá`,ua:`Ватапа`};var d={en:`Vatapá is a dish from Brazil featuring white bread, coconut milk, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used. Uses bread and fresh shrimp for an accessible vatapá, omitting some regional dried-shrimp variations.`,ua:`Ватапа, страва кухні країни Бразилія з такими основними складниками: білий хліб, кокосове молоко, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Для доступної ватапи використано хліб і свіжі креветки без окремих регіональних варіантів із сушеними креветками.`};var g=[{en:`Soak the dried beans in ample clean cold water for about 20 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 20 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:20,i:[[`white-bread`,250,`g`],[`coconut-milk`,450,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`garlic`,5,`clove`],[`shrimp`,300,`g`],[`palm-oil`,55,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`peanut`,130,`g`],[`cashew`,100,`g`],[`ground-ginger`,35,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`fish-stock`,350,`ml`],[`cilantro`,22,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lime-juice`,40,`ml`]]}];var m={slug:n,id:t,country:`BR`,region:s,servings:4,minutes:66,title:l,text:d,steps:g};export{a as country,m as default,t as id,o as minutes,s as region,r as servings,n as slug,g as steps,d as text,l as title};